// Fetch client for the ML API. No dependencies, so it runs in the browser, in Node and in React Native.
// mobile-kit/ml/client.ts is a byte-for-byte copy (run `pnpm ml:kit`).
import type {
  ApiErrorBody,
  ErrorCode,
  InputRow,
  Issue,
  ModelInfo,
  ModelInfoResponse,
  PredictResponse,
} from './types';

export type ClientErrorCode = ErrorCode | 'network' | 'timeout' | 'bad_response';

export class MlApiError extends Error {
  readonly code: ClientErrorCode;
  readonly status: number | null;
  readonly details: Issue[];

  constructor(code: ClientErrorCode, message: string, status: number | null = null, details: Issue[] = []) {
    super(message);
    this.name = 'MlApiError';
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

export type MlClient = {
  getModel(): Promise<ModelInfo>;
  predict(row: InputRow): Promise<PredictResponse>;
  predictMany(rows: InputRow[]): Promise<PredictResponse>;
};

export type MlClientOptions = {
  // Origin of the deployed web app, e.g. https://example.vercel.app. Use '' in the web app itself.
  baseUrl: string;
  fetchImpl?: typeof fetch;
  timeoutMs?: number;
};

export function createMlClient({ baseUrl, fetchImpl, timeoutMs = 10_000 }: MlClientOptions): MlClient {
  const root = baseUrl.replace(/\/+$/, '');
  const doFetch: typeof fetch = fetchImpl ?? ((input, init) => fetch(input, init));

  async function request<T>(path: string, init?: RequestInit): Promise<T> {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    let res: Response;
    try {
      res = await doFetch(`${root}${path}`, { ...init, signal: controller.signal });
    } catch (e) {
      const aborted = controller.signal.aborted;
      throw new MlApiError(aborted ? 'timeout' : 'network', aborted ? 'The ML API did not answer in time.' : String(e));
    } finally {
      clearTimeout(timer);
    }
    let body: unknown;
    try {
      body = await res.json();
    } catch {
      throw new MlApiError('bad_response', `Expected JSON from ${path}, got status ${res.status}.`, res.status);
    }
    const err = body as Partial<ApiErrorBody>;
    if (!res.ok || err.ok === false) {
      const e = err.error;
      throw new MlApiError(e?.code ?? 'bad_response', e?.message ?? `HTTP ${res.status}`, res.status, e?.details ?? []);
    }
    return body as T;
  }

  const post = (inputs: InputRow | InputRow[]) =>
    request<PredictResponse>('/api/predict', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ inputs }),
    });

  return {
    getModel: async () => (await request<ModelInfoResponse>('/api/model')).model,
    predict: (row) => post(row),
    predictMany: (rows) => post(rows),
  };
}
